import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input must be a 1D NumPy array of shape (2,)")
    x = np.clip(x, -5, 5)
    term1 = (x[0]**2 - x[1]) * np.exp(-0.1 * (x[0]**2 + x[1]**2))
    term2 = np.cos(2 * x[0] + x[1]) * np.exp(-0.2 * (x[0]**2 + x[1]**2))
    term3 = 0.2 * x[0] * x[1] / (1 + np.exp(-x[0] + x[1]))
    return float(term1 + term2 + term3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input must be a 1D NumPy array of shape (2,)")
    x = np.clip(x, -5, 5)
    term1 = 0.6 * (x[0]**2 + x[1]**2)
    term2 = 0.4 * np.exp(-0.5 * (x[0]**2 + x[1]**2)) * np.sin(3 * x[0] + x[1])
    term3 = 0.3 * np.power(np.abs(x[0] * x[1]), 0.7) * np.exp(-0.1*(x[0]**2 + x[1]**2))
    return float(term1 + term2 + term3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input must be a 1D NumPy array of shape (2,)")
    x = np.clip(x, -5, 5)

    term1 = np.exp(-0.2 * (x[0]**2 + x[1]**2)) * np.sin(4 * x[0] + 3 * x[1])
    term2 = np.exp(-0.3 * (x[0] - 1)**2 - 0.3 * (x[1] + 1)**2) * (x[0] * x[1] / (1 + x[0]**2 + x[1]**2))
    term3 = 0.5 * np.arcsinh(x[0]**2 - x[1]**2)  # Inverse hyperbolic sine modulation

    return float(1.2 * term1 + 0.8 * term2 + 0.6 * term3)
